# -*- coding: utf-8 -*-
"""g11-sequences-03 = Toán 11 KNTT, Bài 7: Cấp số nhân. Mã ngân hàng câu hỏi: TOAN11-C2-B07."""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'tools'))
from mb_quick import *
import sp_g11

CV = 'Cấp số nhân'
vocab = defs(CV, [
 ('gp', 'geometric sequence', 'cấp số nhân', 'a sequence where each term is the previous term times a fixed number.', 'dãy số mà mỗi số hạng bằng số hạng đứng trước nhân với một số không đổi.', 'The sequence 3, 6, 12, 24 is a geometric sequence.', '\\(u_{n+1}=u_nq\\)'),
 ('cr', 'common ratio', 'công bội', 'the fixed number \\(q\\) we multiply by each time.', 'số không đổi \\(q\\) được nhân vào mỗi lần.', 'The common ratio is 2.', '\\(q\\)'),
 ('compound', 'compound interest', 'lãi kép', 'interest that is added to the money and earns interest again.', 'tiền lãi được cộng vào vốn để sinh lãi tiếp ở kì sau.', 'Compound interest of 8 percent per year.', '\\(A=P(1+r)^n\\)'),
 ('growth', 'growth rate', 'tỉ lệ tăng trưởng', 'the percentage by which a quantity grows each period.', 'phần trăm mà đại lượng tăng sau mỗi kì.', 'The growth rate is 5 percent per year.', '\\(r\\)'),
 ('ratio', 'ratio', 'tỉ số', 'one number divided by another.', 'thương của hai số.', 'The ratio of two consecutive terms.', '')])
goals = [('recognise a geometric sequence and its common ratio;', 'nhận biết [[cấp số nhân]] và [[công bội]];'), ('use \\(u_n=u_1q^{n-1}\\) and \\(u_k^2=u_{k-1}u_{k+1}\\);', 'dùng \\(u_n=u_1q^{n-1}\\) và \\(u_k^2=u_{k-1}u_{k+1}\\);'), ('compute the sum of the first \\(n\\) terms;', 'tính tổng \\(n\\) số hạng đầu;'), ('solve compound-interest and growth problems.', 'giải bài toán [[lãi kép]] và tăng trưởng theo tỉ lệ.')]
phrases = [('<b>Find the common ratio.</b>', 'Tìm công bội.'), ('<b>grows by 5% each year</b>', 'tăng 5% mỗi năm'), ('<b>compound interest</b>', 'lãi kép'), ('<b>each term is twice the previous term</b>', 'mỗi số hạng gấp đôi số hạng trước')]
review = T('Lesson 6: an arithmetic sequence <b>adds</b> \\(d\\) each time. A geometric sequence <b>multiplies</b> by \\(q\\). Percent: increase by \\(r\\%\\) means multiply by \\(1+\\frac{r}{100}\\).', 'Bài 6: cấp số cộng <b>cộng</b> \\(d\\) mỗi lần; cấp số nhân <b>nhân</b> với \\(q\\). Phần trăm: tăng \\(r\\%\\) nghĩa là nhân với \\(1+\\frac{r}{100}\\).')
theory = '<h3>5.1 %s</h3>' % TI('Geometric sequences', 'Cấp số nhân')
theory += BOX('blue', ('Definition', 'Định nghĩa'), T('A sequence \\((u_n)\\) is a <b>geometric sequence</b> if \\(u_{n+1}=u_n\\cdot q\\) for all \\(n\\), with constant \\(q\\) (the <b>common ratio</b>).', 'Dãy số \\((u_n)\\) là [[cấp số nhân]] nếu \\(u_{n+1}=u_n\\cdot q\\) với mọi \\(n\\), trong đó \\(q\\) không đổi gọi là [[công bội]].'), T('Example: \\(3,6,12,24,\\dots\\) has \\(q=2\\); \\(81,27,9,3,\\dots\\) has \\(q=\\frac13\\); \\(1,-2,4,-8,\\dots\\) has \\(q=-2\\). To test: \\(\\dfrac{u_{n+1}}{u_n}\\) is always the same.', 'Ví dụ: \\(3,6,12,24,\\dots\\) có \\(q=2\\); \\(81,27,9,3,\\dots\\) có \\(q=\\frac13\\); \\(1,-2,4,-8,\\dots\\) có \\(q=-2\\). Kiểm tra: thương \\(\\dfrac{u_{n+1}}{u_n}\\) luôn bằng nhau.'))
theory += '<h3>5.2 %s</h3>' % TI('General term and a property', 'Số hạng tổng quát và tính chất')
theory += BOX('mint', ('Formulas', 'Công thức'), M('u_n=u_1\\cdot q^{\\,n-1}\\qquad u_k^2=u_{k-1}\\cdot u_{k+1}'), T('So \\(a,b,c\\) (non-zero) are consecutive terms iff \\(b^2=ac\\). If all terms are positive, \\(u_k=\\sqrt{u_{k-1}u_{k+1}}\\).', 'Vậy \\(a,b,c\\) (khác 0) là ba số hạng liên tiếp khi và chỉ khi \\(b^2=ac\\). Nếu các số hạng dương thì \\(u_k=\\sqrt{u_{k-1}u_{k+1}}\\).'))
theory += '<h3>5.3 %s</h3>' % TI('Sum of the first n terms', 'Tổng n số hạng đầu')
theory += BOX('blue', ('Formula', 'Công thức'), M('S_n=u_1\\cdot\\dfrac{q^n-1}{q-1}\\quad(q\\ne1),\\qquad S_n=nu_1\\ (q=1)'))
theory += '<h3>5.4 %s</h3>' % TI('Growth and compound interest', 'Tăng trưởng và lãi kép')
theory += BOX('mint', ('Compound interest', 'Lãi kép'), T('If you deposit \\(P\\) at rate \\(r\\) per period, after \\(n\\) periods you have \\(A=P(1+r)^n\\). This is a geometric sequence with ratio \\(1+r\\).', 'Gửi \\(P\\) với lãi suất \\(r\\) mỗi kì, sau \\(n\\) kì có \\(A=P(1+r)^n\\). Đó là cấp số nhân với công bội \\(1+r\\).'))
theory += BOX('yellow', ('Watch out!', 'Lưu ý'), T('\\(u_n=u_1q^{n-1}\\): the exponent is \\(n-1\\). Do not confuse \\(S_n\\) with \\(u_n\\).', 'Trong \\(u_n=u_1q^{n-1}\\), số mũ là \\(n-1\\). Không nhầm \\(S_n\\) với \\(u_n\\).'))
examples = EXAMPLE(1, ('Basic', 'Cơ bản'), ('Is it geometric?', 'Có là cấp số nhân không?'), T('Which are geometric? (a) \\(2,6,18,54\\) (b) \\(1,2,3,4\\) (c) \\(16,8,4,2\\).', 'Dãy nào là cấp số nhân? (a) \\(2,6,18,54\\) (b) \\(1,2,3,4\\) (c) \\(16,8,4,2\\).'), ('Compare the ratios of neighbours.', 'So sánh thương của các số hạng kề nhau.'), [T('(a) ratios \\(3,3,3\\): yes, \\(q=3\\).', '(a) thương \\(3,3,3\\): đúng, \\(q=3\\).'), T('(b) ratios \\(2,\\frac32,\\frac43\\): no.', '(b) thương \\(2,\\frac32,\\frac43\\): không.'), T('(c) ratios \\(\\frac12,\\frac12,\\frac12\\): yes, \\(q=\\frac12\\).', '(c) thương \\(\\frac12,\\frac12,\\frac12\\): đúng, \\(q=\\frac12\\).')], T('(a) and (c).', '(a) và (c).'))
examples += EXAMPLE(2, ('Basic', 'Cơ bản'), ('General term', 'Số hạng tổng quát'), T('A geometric sequence has \\(u_1=2\\), \\(q=3\\). Find \\(u_5\\).', 'Cấp số nhân có \\(u_1=2\\), \\(q=3\\). Tìm \\(u_5\\).'), ('Use \\(u_n=u_1q^{n-1}\\).', 'Dùng \\(u_n=u_1q^{n-1}\\).'), [T('\\(u_5=2\\cdot3^4=162\\).', '\\(u_5=2\\cdot3^4=162\\).')], T('\\(u_5=162\\).', '\\(u_5=162\\).'))
examples += EXAMPLE(3, ('Intermediate', 'Trung bình'), ('Find \\(q\\) and \\(u_1\\)', 'Tìm \\(q\\) và \\(u_1\\)'), T('In a geometric sequence with positive terms, \\(u_2=6\\) and \\(u_4=54\\). Find \\(q\\), \\(u_1\\) and \\(S_5\\).', 'Cấp số nhân có các số hạng dương, \\(u_2=6\\), \\(u_4=54\\). Tìm \\(q\\), \\(u_1\\) và \\(S_5\\).'), ('\\(u_4=u_2q^2\\).', '\\(u_4=u_2q^2\\).'), [T('\\(q^2=\\dfrac{54}{6}=9\\), \\(q=3\\) (positive).', '\\(q^2=\\dfrac{54}{6}=9\\), \\(q=3\\) (số hạng dương).'), T('\\(u_1=\\dfrac{u_2}{q}=2\\); \\(S_5=2\\cdot\\dfrac{3^5-1}{3-1}=242\\).', '\\(u_1=\\dfrac{u_2}{q}=2\\); \\(S_5=2\\cdot\\dfrac{3^5-1}{3-1}=242\\).')], T('\\(q=3,\\ u_1=2,\\ S_5=242\\).', '\\(q=3,\\ u_1=2,\\ S_5=242\\).'))
assert 2 * 3 ** 4 == 162 and sum(2 * 3 ** k for k in range(5)) == 242 and 6 * 9 == 54
examples += EXAMPLE(4, ('Intermediate', 'Trung bình'), ('Compound interest', 'Lãi kép'), T('Minh deposits 100 million dong at 8% per year (compound). How much will he have after 3 years? After how many whole years will the money be more than 150 million?', 'Minh gửi 100 triệu đồng, lãi kép 8%/năm. Sau 3 năm có bao nhiêu? Sau ít nhất bao nhiêu năm số tiền vượt 150 triệu?'), ('\\(A_n=100\\cdot1.08^n\\).', '\\(A_n=100\\cdot1{,}08^n\\).'), [T('\\(A_3=100\\cdot1.08^3\\approx125.97\\) million.', '\\(A_3=100\\cdot1{,}08^3\\approx125{,}97\\) triệu.'), T('\\(1.08^5\\approx1.469\\lt1.5\\) and \\(1.08^6\\approx1.587\\gt1.5\\): 6 years.', '\\(1{,}08^5\\approx1{,}469\\lt1{,}5\\) và \\(1{,}08^6\\approx1{,}587\\gt1{,}5\\): 6 năm.')], T('About 125.97 million; 6 years.', 'Khoảng 125,97 triệu; 6 năm.'))
assert round(100 * 1.08 ** 3, 2) == 125.97 and min(n for n in range(1, 30) if 100 * 1.08 ** n > 150) == 6
examples += EXAMPLE(5, ('Advanced', 'Nâng cao'), ('Growth of a population', 'Tăng trưởng dân số'), T('A town has 20 000 people and grows by 3% each year. Find the population after 5 years (round to the nearest person).', 'Một thị trấn có 20 000 dân và tăng 3% mỗi năm. Tìm số dân sau 5 năm (làm tròn đến hàng đơn vị).'), ('Common ratio \\(q=1.03\\).', 'Công bội \\(q=1{,}03\\).'), [T('\\(u_6=20000\\cdot1.03^5\\approx23185\\) (population after 5 years).', 'Dân số sau 5 năm: \\(20000\\cdot1{,}03^5\\approx23185\\).')], T('About 23 185 people.', 'Khoảng 23 185 người.'))
assert round(20000 * 1.03 ** 5) == 23185

def lvl(P):
    u1, q, k = P['t']; v = u1 * q ** (k - 1)
    o1 = M4(1, P['w'][0], P['w'][1], P['gp'][0], P['gp'][1:], 'The ratios of neighbouring terms are equal.', 'Thương của hai số hạng kề nhau luôn bằng nhau.')
    o2 = M4(2, 'A geometric sequence has \\(u_1=%d\\), \\(q=%d\\). Find \\(u_{%d}\\).' % (u1, q, k), 'Cấp số nhân có \\(u_1=%d\\), \\(q=%d\\). Tính \\(u_{%d}\\).' % (u1, q, k), str(v), [str(u1 * q ** k), str(-v), str(u1 + (k - 1) * q), str(v + u1)], '\\(u_{%d}=%d\\cdot(%d)^{%d}=%d\\).' % (k, u1, q, k - 1, v), '\\(u_{%d}=%d\\cdot(%d)^{%d}=%d\\).' % (k, u1, q, k - 1, v))
    a, b, n = P['s']; S = a * (b ** n - 1) // (b - 1)
    o3 = M4(3, 'Find the sum of the first %d terms with \\(u_1=%d\\), \\(q=%d\\).' % (n, a, b), 'Tính tổng %d số hạng đầu của cấp số nhân có \\(u_1=%d\\), \\(q=%d\\).' % (n, a, b), str(S), [str(S + a), str(S - a), str(a * b ** n), str(S + 2)], '\\(S_n=%d\\cdot\\dfrac{%d^{%d}-1}{%d-1}=%d\\).' % (a, b, n, b, S), '\\(S_n=%d\\cdot\\dfrac{%d^{%d}-1}{%d-1}=%d\\).' % (a, b, n, b, S))
    t4 = tf(4, *P['tf4']); x, y, z, tv = P['mid']
    t5 = tf(5, 'The numbers \\(%d,\\ %d,\\ %d\\) are three consecutive terms of a geometric sequence.' % (x, y, z), 'Ba số \\(%d,\\ %d,\\ %d\\) là ba số hạng liên tiếp của một cấp số nhân.' % (x, y, z), tv, 'Check \\(%d^2=%d\\cdot%d\\): %d vs %d.' % (y, x, z, y * y, x * z), 'Kiểm tra \\(%d^2=%d\\cdot%d\\): %d và %d.' % (y, x, z, y * y, x * z))
    i, j, qq, ui = P['q']; uj = ui * qq ** (j - i)
    s6 = sh(6, 'In a geometric sequence with positive terms, \\(u_{%d}=%d\\) and \\(u_{%d}=%d\\). Find \\(q\\).' % (i, ui, j, uj), 'Cấp số nhân có các số hạng dương, \\(u_{%d}=%d\\), \\(u_{%d}=%d\\). Tìm \\(q\\).' % (i, ui, j, uj), qq, '\\(q^{%d}=\\dfrac{%d}{%d}=%d\\), so \\(q=%d\\).' % (j - i, uj, ui, qq ** (j - i), qq), '\\(q^{%d}=\\dfrac{%d}{%d}=%d\\) nên \\(q=%d\\).' % (j - i, uj, ui, qq ** (j - i), qq))
    Pm, rate = P['m']; A = Pm * (100 + rate) ** 2 // 10000; assert A * 10000 == Pm * (100 + rate) ** 2
    s7 = sh(7, 'You deposit %d million dong at %d%% compound interest per year. How many million dong after 2 years?' % (Pm, rate), 'Gửi %d triệu đồng, lãi kép %d%%/năm. Sau 2 năm có bao nhiêu triệu đồng?' % (Pm, rate), A, '\\(A=%d\\cdot(1+%s)^2=%d\\).' % (Pm, rate / 100, A), '\\(A=%d\\cdot(1+%s)^2=%d\\).' % (Pm, str(rate / 100).replace('.', '{,}'), A))
    return [[o1, o2, o3], [t4, t5], [s6, s7]]
PP = [dict(w=('Which sequence is a geometric sequence?', 'Dãy số nào dưới đây là cấp số nhân?'), t=(2, 3, 5), gp=('2,\\ 6,\\ 18,\\ 54', '1,\\ 2,\\ 3,\\ 4', '1,\\ 4,\\ 9,\\ 16', '3,\\ 5,\\ 7,\\ 9'), s=(1, 2, 8), tf4=('The sequence \\(2,6,18,54,\\dots\\) is a geometric sequence.', 'Dãy \\(2,6,18,54,\\dots\\) là cấp số nhân.', True, 'The ratio is always 3.', 'Thương luôn bằng 3.'), mid=(2, 6, 18, True), q=(2, 4, 3, 6), m=(100, 10)),
      dict(w=('Which list of numbers starts a geometric sequence?', 'Danh sách số nào là những số hạng đầu của một cấp số nhân?'), t=(3, -2, 6), gp=('5,\\ -10,\\ 20,\\ -40', '1,\\ 3,\\ 5,\\ 7', '2,\\ 4,\\ 6,\\ 8', '1,\\ 2,\\ 4,\\ 7'), s=(3, 3, 5), tf4=('The sequence \\(1,2,3,4,\\dots\\) is a geometric sequence.', 'Dãy \\(1,2,3,4,\\dots\\) là cấp số nhân.', False, 'The ratios \\(2,\\frac32,\\dots\\) are not equal.', 'Các thương \\(2,\\frac32,\\dots\\) không bằng nhau.'), mid=(3, 6, 10, False), q=(1, 3, 2, 5), m=(200, 20)),
      dict(w=('Choose the geometric sequence.', 'Hãy chọn cấp số nhân.'), t=(1, 2, 10), gp=('1,\\ -2,\\ 4,\\ -8', '4,\\ 7,\\ 10,\\ 13', '1,\\ 1,\\ 2,\\ 3', '2,\\ 3,\\ 5,\\ 8'), s=(2, -2, 6), tf4=('The sequence \\(1,-2,4,-8,\\dots\\) is a geometric sequence with \\(q=-2\\).', 'Dãy \\(1,-2,4,-8,\\dots\\) là cấp số nhân với \\(q=-2\\).', True, 'Each term is \\(-2\\) times the previous term.', 'Mỗi số hạng bằng \\(-2\\) lần số hạng trước.'), mid=(1, 5, 25, True), q=(2, 4, 5, 4), m=(400, 5))]
assert 2 * 3 ** 4 == 162 and 3 * (-2) ** 5 == -96 and 2 ** 9 == 512 and 255 == (2 ** 8 - 1) and 3 * (3 ** 5 - 1) // 2 == 363 and 2 * ((-2) ** 6 - 1) // (-3) == -42
assert 4 * 25 == 100 and 6 * 6 == 36 and 400 * 105 ** 2 == 441 * 10000 and 36 != 3 * 10
practice = LEVEL_PRACTICE(GRP, {lv: lvl(p) for lv, p in zip((1, 2, 3), PP)})
practice = with_self(practice, sp_g11.B7, start=8)
mistakes = [('<b>Using \\(n\\) as the exponent.</b> \\(u_n=u_1q^{n-1}\\).', '<b>Dùng \\(n\\) làm số mũ.</b> \\(u_n=u_1q^{n-1}\\).'), ('<b>Adding instead of multiplying.</b> A geometric sequence multiplies by \\(q\\).', '<b>Cộng thay vì nhân.</b> Cấp số nhân nhân với \\(q\\).'), ('<b>Losing the sign of \\(q\\).</b> If the signs alternate, \\(q\\lt0\\).', '<b>Mất dấu của \\(q\\).</b> Dấu đan xen nghĩa là \\(q\\lt0\\).'), ('<b>Simple interest instead of compound.</b> Compound interest multiplies by \\(1+r\\) each period.', '<b>Nhầm lãi đơn với lãi kép.</b> Lãi kép nhân với \\(1+r\\) mỗi kì.'), ('<b>\\(q=1\\) in the sum formula.</b> Then \\(S_n=nu_1\\).', '<b>Dùng công thức tổng khi \\(q=1\\).</b> Khi đó \\(S_n=nu_1\\).')]
summary = [('Geometric: \\(u_{n+1}=u_nq\\); \\(u_n=u_1q^{n-1}\\).', 'Cấp số nhân: \\(u_{n+1}=u_nq\\); \\(u_n=u_1q^{n-1}\\).'), ('\\(u_k^2=u_{k-1}u_{k+1}\\); \\(S_n=u_1\\dfrac{q^n-1}{q-1}\\).', '\\(u_k^2=u_{k-1}u_{k+1}\\); \\(S_n=u_1\\dfrac{q^n-1}{q-1}\\).'), ('Compound interest: \\(A=P(1+r)^n\\).', 'Lãi kép: \\(A=P(1+r)^n\\).'), ('Key English words: geometric sequence, common ratio, compound interest, growth rate.', 'Từ tiếng Anh cần nhớ: geometric sequence, common ratio, compound interest, growth rate.')]
checks = [('I can find the common ratio.', 'Tôi tìm được công bội.'), ('I can use the general term and the sum.', 'Tôi dùng được số hạng tổng quát và tổng.'), ('I can solve compound-interest problems.', 'Tôi giải được bài toán lãi kép.'), ('I can tell arithmetic from geometric sequences.', 'Tôi phân biệt được cấp số cộng và cấp số nhân.'), STD_SUMMARY_CHECK_EN()]
lesson(id='g11-sequences-03', title_en='Geometric Sequences', title_vi=CV, topic=('Sequences', 'Dãy số. Cấp số cộng và cấp số nhân'), folder='sequences', file='geometric-progressions', catalog_title_vi=CV,
  meta=dict(level=('Intermediate', 'Trung bình'), time=('about 60 minutes', 'khoảng 60 phút'), before=('arithmetic sequences, powers, percentages', 'cấp số cộng, lũy thừa, phần trăm')),
  goals=goals, vocab=vocab, phrases=phrases, review=review, theory=theory, examples=examples, practice=practice, mistakes=mistakes, summary=summary, checks=checks,
  description='Geometric sequences: common ratio, general term, sum and compound interest.', level='Intermediate', minutes=60,
  description_vi='Bài 7 – Cấp số nhân: công bội, số hạng tổng quát, tổng n số hạng đầu, lãi kép và tăng trưởng.', tags_vi=['cấp số nhân', 'công bội', 'lãi kép', 'tăng trưởng'], prerequisites=['g11-sequences-02'], tags=['geometric sequence', 'common ratio', 'compound interest'], order=80)
